changeSet.sql:
CREATE TABLE public.campaign_metric ( id BIGSERIAL NOT NULL, campaign_id BIGINT NOT NULL, metric_date DATE NOT NULL, impressions BIGINT NOT NULL DEFAULT 0, clicks BIGINT NOT NULL DEFAULT 0, conversions BIGINT NOT NULL DEFAULT 0, spend NUMERIC(15,2) NOT NULL DEFAULT 0, revenue NUMERIC(15,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT pk_campaign_metric PRIMARY KEY (id),
CONSTRAINT uk_campaign_metric_date UNIQUE (campaign_id, metric_date),
CONSTRAINT fk_campaign_metric_campaign FOREIGN KEY (campaign_id) REFERENCES public.campaign(id) ON DELETE CASCADE );
CREATE INDEX idx_campaign_metric_date ON public.campaign_metric(metric_date);
CREATE INDEX idx_campaign_metric_campaign ON public.campaign_metric(campaign_id);
